from proto import *
def spir(a0, a1, r0, r1, step=3): return arcpts(lambda a: r0 + (r1-r0)*(a-a0)/(a1-a0), a0, a1, step)
def run(name, tailR=35, tailA=-46, tip=[(24,-24),(18,-23)], headE=[(10,-26),(5,-34),(0,-44),(-3,-54),(-6,-63),(-8,-69)],
        headW=[(-30,-69),(-35,-66),(-39,-59),(-42,-50),(-42,-41),(-39,-32),(-34,-25)], sl=(-150,-172,28,28), north=[], endR=37):
    Hh = spir(0, tailA, tailR, tailR) + tip + headE + headW + spir(*sl) + north + [P(endR,-179.9)]
    F = evaluate(Hh, name); print('   ', deficit(F)); return F
run('a1', headE=[(10,-26),(4,-33),(-2,-42),(-6,-52),(-9,-61),(-12,-69)], headW=[(-32,-69),(-37,-66),(-41,-59),(-43,-50),(-43,-41),(-40,-32),(-34,-25)])
